const input = $input.first().json || {};

function makeOutput({
  success,
  event = {},
  validationStatus,
  checkedFields = [],
  failedFields = [],
  error = null,
  nextAction
}) {
  return {
    success,
    component_id: "C2-F",
    component_version: "v1",
    event_id: event.event_id || null,
    event_type: event.event_type || null,
    source_component: event.component_id || null,
    payload: event.payload || {},
    metadata: event.metadata || {},
    validation: {
      status: validationStatus,
      checked_fields: checkedFields,
      failed_fields: failedFields
    },
    error,
    next_action: nextAction
  };
}

function fail({ event = {}, code, message, details = [], checkedFields = [], failedFields = [] }) {
  return [
    {
      json: makeOutput({
        success: false,
        event,
        validationStatus: "failed",
        checkedFields,
        failedFields,
        error: {
          code,
          message,
          details
        },
        nextAction: "route_to_failure_log"
      })
    }
  ];
}

function isEmpty(value) {
  return value === undefined || value === null || value === "";
}

function isValidEmail(value) {
  if (typeof value !== "string") return false;
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

function parseRule(rule) {
  if (typeof rule !== "string") return { type: null };

  if (rule === "email") return { type: "email" };
  if (rule === "number") return { type: "number" };

  if (rule.startsWith("min_length:")) {
    return {
      type: "min_length",
      value: Number(rule.split(":")[1])
    };
  }

  if (rule.startsWith("allowed:")) {
    return {
      type: "allowed",
      values: rule
        .replace("allowed:", "")
        .split(",")
        .map(v => v.trim())
    };
  }

  return { type: "unknown", raw: rule };
}

// 1. Input object check
if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty.",
    details: [{ field: "root", issue: "Input object is empty." }]
  });
}

// 2. Event object check
if (!input.event || typeof input.event !== "object") {
  return fail({
    code: "MISSING_EVENT_OBJECT",
    message: "Input must include an event object.",
    details: [{ field: "event", issue: "Missing event object." }]
  });
}

const event = input.event;
const config = input.config || {};
const payload = event.payload || {};
const requiredFields = Array.isArray(config.required_fields) ? config.required_fields : [];
const fieldRules = config.field_rules || {};
const defaultNextAction = config.default_next_action || "route_payload";

// 3. Upstream failure check
if (event.success === false) {
  return fail({
    event,
    code: "UPSTREAM_EVENT_FAILED",
    message: "Upstream event was already marked as failed.",
    details: [
      {
        field: "event.success",
        issue: "Cannot validate failed upstream event.",
        upstream_error: event.error || null
      }
    ]
  });
}

// 4. Payload object check
if (!event.payload || typeof event.payload !== "object" || Array.isArray(event.payload)) {
  return fail({
    event,
    code: "MISSING_OR_INVALID_PAYLOAD",
    message: "Event payload must be a JSON object.",
    details: [{ field: "event.payload", issue: "Missing or invalid payload object." }]
  });
}

const checkedFields = [];
const failedFields = [];
const details = [];

// 5. Required field validation
for (const field of requiredFields) {
  checkedFields.push(field);

  if (isEmpty(payload[field])) {
    failedFields.push(field);
    details.push({
      field,
      rule: "required",
      issue: `${field} is required.`
    });
  }
}

// 6. Field rule validation
for (const [field, ruleString] of Object.entries(fieldRules)) {
  if (!checkedFields.includes(field)) {
    checkedFields.push(field);
  }

  const value = payload[field];

  // Avoid duplicate errors if required field already failed
  if (isEmpty(value)) {
    continue;
  }

  const rule = parseRule(ruleString);

  if (rule.type === "email" && !isValidEmail(value)) {
    failedFields.push(field);
    details.push({
      field,
      rule: "email",
      issue: `${field} must be a valid email.`
    });
  }

  if (rule.type === "number" && typeof value !== "number") {
    failedFields.push(field);
    details.push({
      field,
      rule: "number",
      issue: `${field} must be a number.`
    });
  }

  if (rule.type === "min_length") {
    if (typeof value !== "string" || value.length < rule.value) {
      failedFields.push(field);
      details.push({
        field,
        rule: ruleString,
        issue: `${field} must be at least ${rule.value} characters.`
      });
    }
  }

  if (rule.type === "allowed") {
    if (!rule.values.includes(String(value))) {
      failedFields.push(field);
      details.push({
        field,
        rule: ruleString,
        issue: `${field} must be one of: ${rule.values.join(", ")}.`
      });
    }
  }

  if (rule.type === "unknown") {
    failedFields.push(field);
    details.push({
      field,
      rule: rule.raw,
      issue: `Unknown validation rule: ${rule.raw}.`
    });
  }
}

// 7. Validation failure
if (failedFields.length > 0) {
  return fail({
    event,
    code: "VALIDATION_FAILED",
    message: "Payload failed validation.",
    details,
    checkedFields,
    failedFields: [...new Set(failedFields)]
  });
}

// 8. Success
return [
  {
    json: makeOutput({
      success: true,
      event,
      validationStatus: "passed",
      checkedFields,
      failedFields: [],
      error: null,
      nextAction: defaultNextAction
    })
  }
];
